  current_setting('truth.session_id'), NULL,
  to_jsonb($t$His press at 09:16 CST 2026-11-24 in W4's thread: "Write J3, not counted" (as Wall 11552 and audit 41457 give it; Wall 11548 gives the card's choices as "not counted / counted first / hold"). The press chooses option A. W3 did not see the card or the press.$t$::text),
  $j${"answer": "Write J3, not counted", "source": "Wall 11552; audit 41457 (card cmsg_017ZQamDMHrS6fqMHnQDVo58WXJ7tM3PTWEZUuwnF28VBr)", "thread": "W4", "press_time": "09:16 CST 2026-11-24", "question": "not in the record W3 read (the card is in W4's thread); the card text is ask586/w4/j3/card586j3.md 872fe98f"}$j$::jsonb,
  'W4',
  $j${"md5": "7b81e80d", "path": "ask586/w3/plan586.md", "commit": "not read by W3 for this row", "note": "W3's plan rev 6, J3 (W1 PASS with C6 and C7, Wall 11381); the texts are ask586/w3/texts586_J2J3J6.md 78ba341a section 2", "source": "md5sum by W3; Wall 11509"}$j$::jsonb,
  $j$[{"md5": "5ce1849f", "path": "ask586/w4/j3/on591/target_engine_j3_on591.json", "note": "the engine target on the ASK 591 live base 347f3e21 (base E); graded, written and read back", "source": "md5sum by W3; Wall 11548, 11549, 11553"}, {"md5": "9feb7eb0", "path": "ask586/w4/j3/on591/target_child_j3_on591.json", "note": "the child target on e086bb3a; the same md5 as the J2-based child target onj2/target_child_j3_onj2.json", "source": "md5sum by W3; Wall 11548, 11549, 11553"}, {"md5": "5b527f95", "path": "ask586/w4/j3/notes_j3.md", "note": "build notes rev 0", "source": "md5sum by W3"}, {"md5": "bbe0ca1d", "path": "ask586/w4/j3/build_j3.cjs", "note": "the build script, rev 1 (one anchor changed for the J2 base; the inserted text unchanged, Wall 11525)", "source": "md5sum by W3"}, {"md5": "042082bc", "path": "ask586/w4/j3/t_j3.cjs", "note": "the test, 50 cases", "source": "md5sum by W3"}, {"md5": "76ef1be9", "path": "ask586/w4/j3/on591/out_t_j3_on591.txt", "note": "test output on the written target; the same md5 as write/t_j3_at_write.txt", "source": "md5sum by W3"}, {"md5": "5cae14f0", "path": "ask586/w4/j3/write/standing_at_write.txt", "note": "the standing set at the write", "source": "md5sum by W3"}, {"md5": "4204ae6f", "path": "ask586/w4/j3/c7.cjs", "note": "the C7 measure on stored judgments 1263 to 1274", "source": "md5sum by W3"}, {"md5": "c02758d4", "path": "ask586/w4/j3/out_c7.txt", "note": "its output", "source": "md5sum by W3"}, {"md5": "b869d5c8", "path": "ask586/w4/j3/sbrun.cjs", "note": "the end-to-end run of the built send-back builders on row 1274", "source": "md5sum by W3"}, {"md5": "d517182c", "path": "ask586/w4/j3/ogrcmp.cjs", "note": "the comparison of the gatherer with the engine's own grants harvester", "source": "md5sum by W3"}, {"md5": "872fe98f", "path": "ask586/w4/j3/card586j3.md", "note": "the card text", "source": "md5sum by W3"}, {"md5": "7228cc37", "path": "ask586/w4/j3/write/fetchback_eng586j3.json", "note": "fetch-back after the wri