  $j${"copy": "restore the engine and the child together from ask586/w4/j3/write/revert_eng586j3.json 29cec003 and revert_child586j3.json b9773479 (to 347f3e21 and e086bb3a). A revert now would also undo ASK 591 fix 1, written on top.", "path": "ask586/w4/j3/write/revert_eng586j3.json; ask586/w4/j3/write/revert_child586j3.json", "source": "audit 41457; Wall 11552; md5sum by W3; the last sentence is W3's reading of Wall 11556"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS (re-cut on ASK 591 live: only Build Independent Verdict, Panel Build and the Shared Library change; those three equal the J2-based target byte for byte; t_j3 50 PASS; standing set 29 PASS; pair PASS; ASK 591 kept)", "wall_id": 11549, "md5_graded": "5ce1849f", "verdict_norm": "PASS", "source": "Wall 11549; the md5 is in Wall 11548 and is md5sum by W3 on ask586/w4/j3/on591/target_engine_j3_on591.json"}, {"seat": "W1", "verdict": "PASS (the child target: equal to the J2-based child target)", "wall_id": 11549, "md5_graded": "9feb7eb0", "verdict_norm": "PASS", "source": "Wall 11549; Wall 11548; md5sum by W3 on ask586/w4/j3/on591/target_child_j3_on591.json"}]$j$::jsonb,
  ARRAY['5ce1849f','9feb7eb0'], '[41457]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN", "before": "347f3e21, 423 nodes", "after": "137378eb-c1b1-45ab-ab87-0febeab23ac6, 423 nodes"}, {"kind": "n8n workflow", "name": "child MqQHRl7mQQ0z8QdT", "before": "e086bb3a, 156 nodes", "after": "ecdc6218-834d-4658-a90d-088414a22fa3, 156 nodes"}, {"kind": "node", "name": "Panel Build", "before": "no grants paragraph, no grants block", "after": "the J3 paragraph once in the judges' text; the gatherer and THE GRANTS LISTS block above COLLISION POINTS"}, {"kind": "node text", "name": "Build Independent Verdict", "before": "no grants paragraph", "after": "the same paragraph (the node does not run)"}, {"kind": "library lines", "name": "Shared Library lines 3564, 2784, 2789, 2929, 2959, engine and child", "before": "no E-GRT check", "after": "the E-GRT check appended to line 3564; the record inserts"}, {"kind": "library", "name": "Shared Library, engine and child", "before": "LIB b243080d9bd0b10c", "after": "LIB 47a39128fec62d31, MAP efe8431fb6af14e1"}]$j$::jsonb,
  $j$[{"name": "t_j3.cjs, 50 cases", "result": "50 PASS at each build, at W1's reruns and at the write: structure; the gatherer (42071: defender 0, challenger 13; every sentence whole; a 480-character sentence served whole); the check on known-bad row 1274 (two lines, fault 1), G5 passes, G5547 fault 1, G99 fault 2, NOT A LISTED GRANT fault 3; a 2,120-character judge line stored whole; the record KEEP CURED, CHANGE CURED, silent and error, none counted", "source": "Wall 11508; 11509; 11548; 11549; 11552; notes_j3.md section 2"}, {"name": "sbprobe.cjs and sbrun.cjs, end to end on row 1274", "result": "the built Send Back Build and Alt Send Back Build give two E-GRT items that reach the judge's message whole (1,320 and 1,245 characters)", "source": "notes_j3.md section 2"}, {"name": "ogrcmp.cjs", "result": "on runs 32643, 37203, 41822 and 42071 the defender list has the same count and order as the engine's own harvester (25, 18, 0, 0)", "source": "notes_j3.md section 2"}, {"name": "Standing set (ASK 596 core)", "result": "29 PASS, 0 FAIL on the target at the write and on live at the readback; the baseline adds the place __gl", "source": "Wall 11509; 11549; 11552; 11553"}, {"name": "Library Check pair", "result": "PASSES: LIB 47a39128fec62d31", "source": "Wall 11549; 11552; 11553"}, {"name": "c7.cjs on stored judgments 1263 to 1274", "result": "4 of 67 break lines would go back, all fault 1; none for a grant word used of something other than a grant; run 42071 2 of 13", "source": "notes_j3.md section 3; out_c7.txt"}]$j$::jsonb,
  $j$[{"seat": "W1", "wall_id": 11553, "result": "MATCH (own fetch: engine 137378eb, 423 nodes; child ecdc6218, 156; target and fetch-back against live 0 differences; from the prior live only Build Independent Verdict, Panel Build and the Shared Library, child the Shared Library; t_j3 50 PASS; standing set 29 PASS; pair PASS)"}]$j$::jsonb,
  $j${"case": "UNEXERCISED. No run has executed on 137378eb or a later version (debate_results last row 21:57 CST 2026-11-23). EXPECT on the first run: each judge request holds THE GRANTS LISTS block once, above the COLLISION POINTS instructions, with no sentence cut; a break line that uses a grant word names a G number of that side's list or NOT A LISTED GRANT, or makes one debate_enforcer_log row of rule E-GRT whose flagged_line is the judge's whole line and whose cure_reason holds \"record-only, counts against no seat\"; no seat count moves by it.", "source": "Wall 11552, 11553; SQL by W3; the EXPECT is W3's reading"}$j$::jsonb,
